-- Idempotent public resource records for work areas that previously had no dedicated content.
-- The live database was updated with this same seed on 2026-10-23.
insert into public.work_area_content
  (work_area, title, description, link_url, link_label, sort_order, is_active)
select seed.work_area, seed.title, seed.description, seed.link_url, seed.link_label, seed.sort_order, true
from (values
  ('वरिष्ठ नागरिक सहायता','वरिष्ठ नागरिक कल्याण और अधिकार','वरिष्ठ नागरिकों के कल्याण, सामाजिक सुरक्षा और विभागीय सहायता से संबंधित आधिकारिक जानकारी। पात्रता और आवेदन नियम संबंधित विभाग से जाँचें।','https://socialjustice.gov.in/','सामाजिक न्याय मंत्रालय',10),
  ('वरिष्ठ नागरिक सहायता','वरिष्ठ नागरिकों के लिए सरकारी योजनाएँ','पेंशन, स्वास्थ्य, सहायक उपकरण और सामाजिक सुरक्षा से जुड़ी उपलब्ध योजनाएँ खोजें। राज्य-विशेष नियम अलग हो सकते हैं।','https://www.myscheme.gov.in/search','सरकारी योजनाएँ खोजें',20),
  ('वरिष्ठ नागरिक सहायता','सहायता अनुरोध और मार्गदर्शन','यदि किसी वरिष्ठ नागरिक को सहायता चाहिए, तो सदस्य लॉगिन से अनुरोध भेजें। आपात स्थिति में स्थानीय प्रशासन या आधिकारिक आपात सेवा से संपर्क करें.',null,null,30),
  ('आपदा एवं राहत कार्य','आपदा तैयारी और सुरक्षा निर्देश','बाढ़, गर्मी, भूकंप और अन्य आपदाओं के लिए तैयारी तथा आधिकारिक चेतावनियों की जानकारी। स्थानीय प्रशासन के निर्देशों का पालन करें।','https://ndma.gov.in/','राष्ट्रीय आपदा प्रबंधन प्राधिकरण',10),
  ('आपदा एवं राहत कार्य','आपातकालीन सहायता और राहत जानकारी','आपदा के समय आधिकारिक राहत सूचना, सुरक्षित निकासी और संबंधित विभाग की सहायता जानकारी देखें। अफवाहों के बजाय सरकारी निर्देशों पर भरोसा करें।','https://ndrf.gov.in/','राष्ट्रीय आपदा मोचन बल',20),
  ('आपदा एवं राहत कार्य','आपदा सहायता अनुरोध','राहत, आवश्यक सामग्री या स्वयंसेवी सहयोग के लिए सदस्य लॉगिन से अनुरोध दर्ज करें। यह फॉर्म सरकारी आपात सेवा का विकल्प नहीं है.',null,null,30),
  ('दिव्यांगजन सहायता','दिव्यांगजन अधिकार और सरकारी सहायता','दिव्यांगजनों के अधिकार, समावेशन, सुगम्यता और विभागीय योजनाओं की आधिकारिक जानकारी। आवेदन से पहले पात्रता और नवीनतम दिशा-निर्देश जाँचें।','https://depwd.gov.in/','दिव्यांगजन सशक्तिकरण विभाग',10),
  ('दिव्यांगजन सहायता','विशिष्ट दिव्यांगता पहचान पत्र (UDID)','UDID कार्ड और संबंधित आवेदन/सेवा की जानकारी आधिकारिक पोर्टल पर देखें। दस्तावेज़ और प्रक्रिया पोर्टल के वर्तमान निर्देशों के अनुसार पूरी करें।','https://swavlambancard.gov.in/','UDID आधिकारिक पोर्टल',20),
  ('दिव्यांगजन सहायता','दिव्यांगजन के लिए योजनाएँ','शिक्षा, कौशल, रोजगार और सहायता सेवाओं से संबंधित सरकारी योजनाएँ खोजें; पात्रता संबंधित योजना के नियमों पर निर्भर करती है।','https://www.myscheme.gov.in/search','सरकारी योजनाएँ खोजें',30),
  ('व्यापार एवं स्वरोजगार','उद्यम पंजीकरण की आधिकारिक जानकारी','सूक्ष्म, लघु और मध्यम उद्यम (MSME) के लिए उद्यम पंजीकरण और संबंधित आधिकारिक मार्गदर्शन देखें। किसी एजेंट को शुल्क देने से पहले आधिकारिक पोर्टल जाँचें।','https://udyamregistration.gov.in/','उद्यम पंजीकरण पोर्टल',10),
  ('व्यापार एवं स्वरोजगार','स्वरोजगार और उद्यमिता योजनाएँ','व्यवसाय शुरू करने, प्रशिक्षण, ऋण या सहायता से जुड़ी योजनाओं को सरकारी योजना खोज पोर्टल पर देखें। स्वीकृति पात्रता और विभागीय प्रक्रिया पर निर्भर है।','https://www.myscheme.gov.in/search','सरकारी योजनाएँ खोजें',20),
  ('व्यापार एवं स्वरोजगार','व्यवसाय योजना और कौशल मार्गदर्शन','व्यवसाय योजना, बाजार की जरूरत, लागत, लेखा और कौशल प्रशिक्षण की तैयारी करें। SBPF सामग्री सामान्य मार्गदर्शन है, वित्तीय या कानूनी गारंटी नहीं।','https://www.skillindiadigital.gov.in/','कौशल विकास पोर्टल',30)
) as seed(work_area,title,description,link_url,link_label,sort_order)
where not exists (
  select 1 from public.work_area_content existing
  where existing.work_area = seed.work_area and existing.title = seed.title
);
